CREATE DATABASE IF NOT EXISTS wifi_manager CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE wifi_manager;
CREATE TABLE IF NOT EXISTS admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(admin_id),FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS enrollment_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,created_by BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,used_device_id VARCHAR(128) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES admins(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS devices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,device_id VARCHAR(128) NOT NULL UNIQUE,hostname VARCHAR(255),os_name VARCHAR(100),app_version VARCHAR(40),device_token_hash CHAR(64) UNIQUE,last_ip VARCHAR(64),connection_status ENUM('online','offline') NOT NULL DEFAULT 'offline',last_heartbeat_at DATETIME NULL,wifi_ssid VARCHAR(255),wifi_bssid VARCHAR(64),wifi_signal VARCHAR(32),wifi_radio VARCHAR(64),wifi_channel VARCHAR(32),wifi_connected_at DATETIME NULL,last_scan_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scan_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,device_id VARCHAR(128) NOT NULL,requested_by BIGINT UNSIGNED NOT NULL,requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,result_json JSON NULL,INDEX(device_id),INDEX(completed_at),FOREIGN KEY(requested_by) REFERENCES admins(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS device_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,device_id VARCHAR(128) NOT NULL,event_type VARCHAR(80) NOT NULL,payload JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_device_events_device (device_id),INDEX idx_device_events_created (created_at));